|Members = [[Angela Rummans]]<br>[[Brett Robinson]]<br>[[Kaycee Clark]]<br>[[Rachel Swindler]]<br>[[Tyler Crispen]]<br>[[Winston Hines]]<br>'''Affiliates''':<br>[[JC Mounduix]]<br>[[Kaitlyn Herman]]<br>[[Sam Bledsoe]]
|Defectors = [[Brett Robinson]]
|Votes = 29
|HOHs = 8 (Weeks 1, 6, 9, <br> 10, 11, Day 86, <br> Weeks 12 & 13)
|Nominations = 15 (Weeks 2, 3, 5, 6, <br> 7, 8, Days 86 & 91, <br> & Week 13)
|Vetos = 8 (Weeks 2, 5, 6, 7,<br>8, 9, Days 86 & 92)
